'use client'
import { cn, useControllableSignal, useRovingFocus, useSignals } from '@cascivo/core'
import { forwardRef } from 'react'
import type { HTMLAttributes, ReactNode } from 'react'
import styles from './toggle-group.module.css'

export interface ToggleGroupItem {
  value: string
  label?: string
  icon?: ReactNode
  /**
   * When true, disables the control and removes it from the tab order.
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  disabled?: boolean
}

export interface ToggleGroupProps extends Omit<
  HTMLAttributes<HTMLDivElement>,
  'onChange' | 'defaultValue'
> {
  type: 'single' | 'multiple'
  value?: string | string[]
  defaultValue?: string | string[]
  onValueChange?: (value: string | string[]) => void
  items: ToggleGroupItem[]
  /**
   * Axis the options flow along: `horizontal` for a segmented row, `vertical` for a stacked
   * column.
   *
   * @defaultValue `horizontal`
   * @see the component manifest
   */
  orientation?: 'horizontal' | 'vertical'
  size?: 'sm' | 'md' | 'lg'
  /**
   * When true, disables the control and removes it from the tab order.
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  disabled?: boolean
}

function isSelected(current: string | string[] | undefined, value: string): boolean {
  if (Array.isArray(current)) return current.includes(value)
  return current === value
}

export const ToggleGroup = forwardRef<HTMLDivElement, ToggleGroupProps>(function ToggleGroup(
  {
    type,
    value,
    defaultValue,
    onValueChange,
    items,
    orientation = 'horizontal',
    size = 'md',
    disabled = false,
    className,
    ...props
  },
  ref,
) {
  useSignals()
  const emptyDefault: string | string[] = type === 'multiple' ? [] : ''
  const [selected, setSelected] = useControllableSignal<string | string[]>({
    value,
    defaultValue: defaultValue ?? emptyDefault,
    onChange: onValueChange,
  })

  const roving = useRovingFocus({ orientation, loop: true })

  const toggle = (itemValue: string) => {
    const current = selected.value
    if (type === 'multiple') {
      const list = Array.isArray(current) ? current : []
      const next = list.includes(itemValue)
        ? list.filter((v) => v !== itemValue)
        : [...list, itemValue]
      setSelected(next)
    } else {
      // Single: clicking the active item clears it.
      setSelected(current === itemValue ? '' : itemValue)
    }
  }

  return (
    <div
      role={type === 'single' ? 'radiogroup' : 'group'}
      data-orientation={orientation}
      data-size={size}
      className={cn(styles['toggleGroup'], className as string | undefined)}
      ref={ref}
      {...props}
    >
      {items.map((item, index) => {
        const on = isSelected(selected.value, item.value)
        const itemDisabled = disabled || item.disabled
        const { ref: itemRef, ...rovingProps } = roving.getItemProps(index)
        const ariaProps =
          type === 'single'
            ? { role: 'radio' as const, 'aria-checked': on }
            : { 'aria-pressed': on }
        return (
          <button
            key={item.value}
            type="button"
            {...ariaProps}
            {...rovingProps}
            ref={itemRef}
            data-state={on ? 'on' : 'off'}
            disabled={itemDisabled}
            aria-label={item.icon && !item.label ? item.value : undefined}
            className={styles['item']}
            onClick={() => toggle(item.value)}
          >
            {item.icon}
            {item.label && <span>{item.label}</span>}
          </button>
        )
      })}
    </div>
  )
})

@layer cascivo.component {
  .toggleGroup {
    display: inline-flex;
    gap: var(--cascivo-space-1);
    padding: var(--cascivo-space-1);
    border-radius: var(--cascivo-radius-control);
    background-color: var(--cascivo-color-bg-subtle);

    &[data-orientation='horizontal'] {
      flex-direction: row;
    }

    &[data-orientation='vertical'] {
      flex-direction: column;
    }

    &[data-size='sm'] {
      --_item-h: var(--cascivo-control-height-sm);
      --_item-font: var(--cascivo-text-sm);
    }

    &[data-size='md'] {
      --_item-h: var(--cascivo-control-height-md);
      --_item-font: var(--cascivo-text-sm);
    }

    &[data-size='lg'] {
      --_item-h: var(--cascivo-control-height-lg);
      --_item-font: var(--cascivo-text-base);
    }
  }

  .item {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--cascivo-space-2);
    block-size: var(--_item-h, var(--cascivo-control-height-md));
    padding-inline: var(--cascivo-space-3);
    font-family: var(--cascivo-font-sans);
    font-size: var(--_item-font, var(--cascivo-text-sm));
    font-weight: var(--cascivo-font-medium);
    line-height: var(--cascivo-leading-none);
    white-space: nowrap;
    cursor: pointer;
    border: 1px solid transparent;
    border-radius: var(--cascivo-radius-item, var(--cascivo-radius-control));
    background-color: transparent;
    color: var(--cascivo-color-text);
    transition:
      background-color var(--cascivo-duration-150) var(--cascivo-ease-out),
      color var(--cascivo-duration-150) var(--cascivo-ease-out),
      box-shadow var(--cascivo-duration-150) var(--cascivo-ease-out);

    &:hover:not(:disabled) {
      background-color: var(--cascivo-color-surface);
    }

    &:focus-visible {
      outline: none;
      box-shadow: var(--cascivo-focus-ring);
    }

    &:disabled {
      opacity: 0.5;
      cursor: not-allowed;
    }

    &[data-state='on'] {
      background-color: var(--cascivo-color-surface);
      color: var(--cascivo-color-text);
      box-shadow: var(--cascivo-shadow-sm);
    }
  }
}

@media (forced-colors: active) {
  .item[data-state='on'] {
    border-color: Highlight;
  }

  .item:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: 2px;
  }

  .item:disabled {
    color: GrayText;
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'ToggleGroup',
  description: 'A set of toggle buttons for single or multiple selection',
  category: 'inputs',
  // Selection runs through JS-only buttons — nothing can be toggled without JS.
  clientJs: 'required',
  states: ['on', 'off'],
  variants: ['single', 'multiple'],
  sizes: ['sm', 'md', 'lg'],
  props: [
    {
      name: 'type',
      description: "Whether one or multiple items can be pressed at once ('single' | 'multiple').",
      type: "'single' | 'multiple'",
      required: true,
    },
    {
      name: 'value',
      description: 'The controlled value.',
      type: 'string | string[]',
      required: false,
    },
    {
      name: 'defaultValue',
      description: 'The initial value when uncontrolled.',
      type: 'string | string[]',
      required: false,
    },
    {
      name: 'onValueChange',
      description: 'Called with the new value when it changes.',
      type: '(value: string | string[]) => void',
      required: false,
    },
    {
      name: 'items',
      description: 'The items to render.',
      type: '{ value: string; label?: string; icon?: React.ReactNode; disabled?: boolean }[]',
      required: true,
    },
    {
      name: 'orientation',
      description:
        'Axis the options flow along: `horizontal` for a segmented row, `vertical` for a stacked column.',
      type: "'horizontal' | 'vertical'",
      required: false,
      default: 'horizontal',
    },
    {
      name: 'size',
      description: "Visual size of the component (e.g. 'sm', 'md', 'lg').",
      type: "'sm' | 'md' | 'lg'",
      required: false,
      default: 'md',
    },
    {
      name: 'disabled',
      description: 'When true, disables the control and removes it from the tab order.',
      type: 'boolean',
      required: false,
      default: 'false',
    },
  ],
  tokens: [
    '--cascivo-control-height-sm',
    '--cascivo-control-height-md',
    '--cascivo-control-height-lg',
    '--cascivo-radius-control',
    '--cascivo-radius-item',
    '--cascivo-color-bg-subtle',
    '--cascivo-color-surface',
    '--cascivo-color-text',
    '--cascivo-shadow-sm',
    '--cascivo-focus-ring',
  ],
  accessibility: {
    role: 'radiogroup',
    wcag: '2.2-AA',
    keyboard: ['ArrowRight', 'ArrowLeft', 'ArrowUp', 'ArrowDown', 'Home', 'End', 'Enter', 'Space'],
    apgPattern: 'radiogroup',
    forcedColors: true,
  },
  examples: [
    {
      title: 'Single selection',
      code: '<ToggleGroup type="single" defaultValue="left" items={[{ value: "left", label: "Left" }, { value: "center", label: "Center" }, { value: "right", label: "Right" }]} />',
    },
    {
      title: 'Multiple selection',
      code: '<ToggleGroup type="multiple" defaultValue={["bold"]} items={[{ value: "bold", label: "Bold" }, { value: "italic", label: "Italic" }]} />',
    },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['selection', 'segmented', 'toolbar', 'choice'],
  intent: {
    whenToUse: [
      'Choosing one value from a small, mutually exclusive set that should stay visible (type="single")',
      'Toggling several independent options in a compact segmented control (type="multiple")',
    ],
    whenNotToUse: [
      'The options are independent actions, not a selection — use ButtonGroup',
      'There are many options or they need labels and descriptions — use Radio or Checkbox groups',
    ],
    antiPatterns: [
      {
        bad: '<ToggleGroup type="single" items={items} onValueChange={save} />',
        good: '<ToggleGroup type="single" value={align} onValueChange={setAlign} items={items} />',
        why: 'Single-select used as a controlled value should be driven by value/onValueChange so the source of truth lives with the parent',
      },
    ],
    related: [
      {
        name: 'ButtonGroup',
        relationship: 'alternative',
        reason: 'Use when the buttons fire independent actions rather than select a value',
      },
      {
        name: 'Toggle',
        relationship: 'alternative',
        reason: 'Use a single Toggle for one standalone binary option',
      },
    ],
    a11yRationale:
      'Single mode renders role="radiogroup" with role="radio" + aria-checked items; multiple mode uses a plain group of buttons with aria-pressed. Roving tabindex makes the set one tab stop and arrow keys move between items, matching the APG radiogroup/toolbar patterns',
    content: {
      tone: 'Short noun or icon per option',
      notes:
        'Keep item labels parallel and concise; provide a label or icon meaningful out of context',
    },
    flexibility: [
      {
        area: 'token names',
        level: 'strict',
        note: 'Item height must resolve to --cascivo-control-height-* to align with other controls',
      },
      {
        area: 'item content',
        level: 'flexible',
        note: 'Items may use a text label, an icon, or both; consumer owns the icon set',
      },
    ],
  },
}
